// Some portions generated by Codex
package org.eclipse.rdf4j.http.client.spi;

import static org.assertj.core.api.Assertions.assertThat;

import java.net.URI;

import org.junit.jupiter.api.Test;

class HttpRequestRedirectPolicyTest {

	@Test
	void defaultRequestAllowsClientConfiguredRedirects() {
		HttpRequest request = HttpRequest.newBuilder("GET", URI.create("https://example.org/source")).build();
		assertThat(request.isRedirectsAllowed()).isTrue();
	}

	@Test
	void copyToAnotherUriRetainsRedirectRestriction() {
		HttpRequest original = HttpRequest.newBuilder("DELETE", URI.create("https://example.org/source"))
				.redirectsAllowed(false)
				.build();
		HttpRequest copy = HttpRequest.copyOf(original, URI.create("https://example.org/other")).build();
		assertThat(copy.isRedirectsAllowed()).isFalse();
		assertThat(copy.getUri()).isEqualTo(URI.create("https://example.org/other"));
	}
}
